/** Default server name (prisma/catalog.ts's setupScript and the schema default). */
export const VALHEIM_DEFAULT_SERVER_NAME = "Nxeon";

/**
 * PURE decision for the Valheim SERVER_NAME setting. `set` is the value to
 * write into the env-file (null = leave the container alone); `note` is a
 * customer-facing explanation when a requested name was ignored.
 */
export function planValheimServerName(
  desiredRaw: unknown,
  current: string | undefined,
  password: string
): { set: string | null; note?: string } {
  if (desiredRaw == null) return { set: null };
  const desired = String(desiredRaw).trim();
  if (desired.length === 0 || desired === VALHEIM_DEFAULT_SERVER_NAME) return { set: null };
  if (current === desired) return { set: null };
  const field = schemaFor("valheim")?.fields.find((f) => f.key === "SERVER_NAME");
  const bad = field ? stringFieldError(field, desired) : "invalid";
  if (bad) return { set: null, note: `Ignored the server name: ${bad}` };
  if (password.length >= 5 && desired.toLowerCase().includes(password.toLowerCase())) {
    return { set: null, note: "Ignored the server name: Valheim won't start if the server name contains the password." };
  }
  return { set: desired };
}

