async function recordUpdateResult(serverId: string, result: string): Promise<void> {
  await db.gameRuntime
    .upsert({
      where: { serverId },
      create: { serverId, lastUpdateAt: new Date(), lastUpdateResult: result.slice(0, 1000) },
      update: { lastUpdateAt: new Date(), lastUpdateResult: result.slice(0, 1000) },
    })
    .catch((e) => console.error("[game-update] could not record result", e));
}

type LoadedServer = Awaited<ReturnType<typeof loadGameServer>>;

/**
 * Move a pinned VERSION to the newest platform-supported one — safely.
 *
 *  1. Only when the game is RUNNING right now (a stopped server is left alone;
 *     updating it would mean starting it, which the owner did not ask for).
 *  2. World backup FIRST, into GAME_BACKUP_DIR (the same archive "Back up now"
 *     makes, downloadable from Manage → Worlds). No backup → no update.
 *  3. Apply through the family's verified real-apply path
 *     (worker/game-config.ts applyMinecraft/applyBedrock), which recreates the
 *     container on the new VERSION — and the right Java image for it.
 *  4. Verify the game really answers again (port check on the public path).
 *  5. If it does not: put the previous VERSION back the same way and say so —
 *     the backup taken in step 2 is named in the message for a full restore.
 * Every step is logged (AuditLog + GameRuntime.lastUpdateResult) and the
 * customer is told exactly what changed.
 */
async function versionBump(
  job: Job,
  server: LoadedServer,
  family: GameFamily,
  plan: Extract<AutoUpdatePlan, { kind: "bump" }>,
  values: Record<string, string | number | boolean>,
  href: string
): Promise<void> {
  const name = schemaFor(family)?.label ?? family;
  const spec = controlSpec(family);
  if (!spec) throw new Error(`game update: no control spec for ${family}`);
  const rt = (await db.server.findUnique({ where: { id: server.id }, select: RUNTIME_SERVER_SELECT })) as RuntimeServer | null;
  const pre = rt ? await probeGameRuntime(rt, { external: false }) : null;
  if (serviceRunning(pre?.probe) !== true) {
    const msg = `Skipped the ${name} update ${plan.from} → ${plan.to}: your server isn't running, and updating it would mean starting it. Start it and the next check will update it.`;
    await recordUpdateResult(server.id, msg);
    console.log(`[game-update] ${server.hostname}: ${msg}`);
    return;
  }

  const backup = await createWorldBackup(server as unknown as SftpServer, spec, "pre-update").catch((e) => ({ ok: false as const, msg: String(e?.message ?? e) }));
  if (!backup.ok) {
    const msg = `Did NOT update ${name} ${plan.from} → ${plan.to}: the safety backup of your world failed (${backup.msg}). Nothing was changed.`;
    await recordUpdateResult(server.id, msg);
    await notifyFailureOnce(server.userId, server.id, `${name} update skipped on ${server.hostname}`, msg, href);
    throw new Error(`game update: pre-update backup failed: ${backup.msg}`);
  }

  const setVersion = async (v: string) => {
    const fresh = await db.server.findUnique({ where: { id: server.id }, select: { gameConfig: true } });
    const cfg = { ...((fresh?.gameConfig as Record<string, unknown> | null) ?? {}), VERSION: v };
    await db.server.update({ where: { id: server.id }, data: { gameConfig: cfg as any } });
  };
  const applyAndVerify = async (v: string) => {
    const out = await applyRealConfig(server as any, family, { ...values, VERSION: v });
    const port = await waitForGamePort(server as unknown as ControlServer, spec.powerStartTimeoutMs ?? 180_000, 5_000);
    return { out, up: out.ok && (port ? port.ok : true), portErr: port?.error ?? null };
  };

  await setVersion(plan.to);
  const res = await applyAndVerify(plan.to).catch((e) => ({ out: { ok: false, applied: [], notes: [String(e?.message ?? e)] }, up: false, portErr: null }));
  const after = rt ? await probeGameRuntime(rt).catch(() => null) : null;
  if (after) await saveRuntime(server.id, after);

  if (res.up) {
    const msg = `Updated ${name} from ${plan.from} to ${plan.to}, restarted and verified it's accepting connections. A backup of your world from just before the update is at ${backup.archive}.`;
    await recordUpdateResult(server.id, msg);
    await db.auditLog
      .create({ data: { userId: null, action: "gameserver.auto_update", detail: `${server.hostname} ${family} ${plan.from} -> ${plan.to} backup=${backup.archive}` } })
      .catch(() => {});
    await notify(server.userId, `${name} updated to ${plan.to} on ${server.hostname}`, msg, href);
    // Re-resolve the server's mods against the new version (worker/mod-autoupdate.ts).
    if (await db.serverMod.count({ where: { serverId: server.id, status: "INSTALLED" } }).catch(() => 0)) await queueAfterGameUpdate(server.id);
    return;
  }

  // Roll back the version.
  await setVersion(plan.from);
  const back = await applyAndVerify(plan.from).catch(() => ({ up: false }));
  const final = rt ? await probeGameRuntime(rt).catch(() => null) : null;
  if (final) await saveRuntime(server.id, final);
  const why = [...(res.out.notes ?? []), res.portErr ?? ""].filter(Boolean).join(" ").slice(0, 300);
  const msg = back.up
    ? `Tried to update ${name} from ${plan.from} to ${plan.to}, but it didn't come back online (${why || "no detail"}), so we put ${plan.from} back and it's running again. Your pre-update world backup is at ${backup.archive}.`
    : `Tried to update ${name} from ${plan.from} to ${plan.to}; it didn't come back online and restoring ${plan.from} didn't bring it back either. Our team has been alerted. Your pre-update world backup is at ${backup.archive}.`;
  await recordUpdateResult(server.id, msg);
  await db.auditLog
    .create({ data: { userId: null, action: "gameserver.auto_update_failed", detail: `${server.hostname} ${family} ${plan.from} -> ${plan.to} rolledBack=${back.up} backup=${backup.archive}` } })
    .catch(() => {});
  await notify(server.userId, `${name} update to ${plan.to} rolled back on ${server.hostname}`, msg, href);
  if (!back.up) {
    await notifyAdmins(`Game update left ${server.hostname} down`, msg, `/admin/servers/${server.id}`).catch(() => {});
  }
  // A retry would back up and try the same failing version again — never.
  await noRetry(job.id);
  throw new Error(`game update not verified: ${msg}`);
}

/**
 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
 * auto-update and has no job already in flight. Idempotent / safe to call on a
 * timer. Returns nothing; logs a summary.
 */
export async function gameUpdateSweep(): Promise<void> {
  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
  const allCandidates = await db.server.findMany({
    where: {
      status: "RUNNING",
      autoUpdate: true,
      osTemplate: { family: { in: [...GAME_FAMILIES] } },
    },
    select: { id: true, hostname: true, gameConfig: true, osTemplate: { select: { family: true } }, gameRuntime: { select: { intent: true } } },
  });
  if (allCandidates.length === 0) return;

  // Skip a server whose game SERVICE the customer deliberately stopped through
  // the dashboard — see eligibleForUpdateSweep's doc comment. `Server.status`
  // (checked above) is the VM's power state and can't see this.
  // Also honour the recorded run intent (lib/game-runtime.ts) — `_serviceState`
  // is erased by older code paths; GameRuntime.intent is not.
  const candidates = allCandidates.filter((s) => eligibleForUpdateSweep(s.gameConfig) && s.gameRuntime?.intent !== "stopped");
  const skippedStopped = allCandidates.length - candidates.length;

  let enqueued = 0;
  for (const s of candidates) {
    const inflight = await db.job.count({
      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (inflight > 0) continue;
    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
    enqueued++;
  }
  if (enqueued > 0 || skippedStopped > 0) {
    const checkOnly = candidates.filter((s) => !hasUpdateSource(s.osTemplate.family as GameFamily)).length;
    console.log(
      `[game-update] sweep enqueued ${enqueued} job(s)` +
        (checkOnly > 0
          ? ` (${checkOnly} candidate(s) are families with no update source — those runs verify the unit is ` +
            `up and change nothing)`
          : "") +
        (skippedStopped > 0
          ? ` (${skippedStopped} candidate(s) skipped — game service deliberately stopped by the customer)`
          : "")
    );
  }
}
/**
 * Should a Minecraft VERSION bump (worker/game-update.ts versionBump) wait for
 * the server's mods? Conservative by design:
 *
 *  - only mod-loader servers (Fabric/Quilt/Forge/NeoForge): their mods are
 *    compiled against one game version and crash the server on another.
 *    Paper/Spigot plugins usually keep working across versions and their
 *    published version lists are often incomplete, so plugin servers are
 *    never held — at most warned;
 *  - only when the owner has mod auto-update on (mode != OFF) and
 *    "hold game updates" enabled (the default);
 *  - only from facts the NX Labs catalogue holds (ModVersion rows / GameMod
 *    version lists); a mod we know nothing about never holds the game.
 *
 * Hold = at least one installed mod has NO known build for the new version.
 */
import { db } from "../db";
import { acceptedLoaders } from "../mods/installers/minecraft";
import { gameVersionMatches } from "./version";

export type BumpMod = {
  name: string;
  /** Builds the catalogue knows: their loaders + game versions. */
  builds: { loaders: string[]; gameVersions: string[] }[];
  /** Project-level game versions (GameMod.gameVersions). */
  projectVersions: string[];
};

export function judgeGameBump(input: { variant: string | null; toVersion: string; mods: BumpMod[] }): { hold: boolean; blockers: string[]; unknown: string[]; reason: string } {
  const variant = (input.variant ?? "").toLowerCase();
  if (!["fabric", "quilt", "forge", "neoforge"].includes(variant)) return { hold: false, blockers: [], unknown: [], reason: "Plugin/vanilla servers aren't held for mods." };
  const accepted = acceptedLoaders(variant);
  const blockers: string[] = [];
  const unknown: string[] = [];
  for (const m of input.mods) {
    const relevant = m.builds.filter((b) => !b.loaders.length || b.loaders.some((l) => accepted.includes(l.toLowerCase())));
    const lists = [...relevant.flatMap((b) => b.gameVersions), ...m.projectVersions];
    if (!lists.length) { unknown.push(m.name); continue; }
    const ok = relevant.some((b) => b.gameVersions.some((g) => gameVersionMatches(g, input.toVersion))) || (!relevant.length && m.projectVersions.some((g) => gameVersionMatches(g, input.toVersion)));
    if (!ok) blockers.push(m.name);
  }
  if (!blockers.length) return { hold: false, blockers, unknown, reason: unknown.length ? `No version data for ${unknown.join(", ")} — not holding the update for them.` : `Every installed mod has a build for ${input.toVersion}.` };
  return {
    hold: true,
    blockers,
    unknown,
    reason: `${blockers.slice(0, 5).join(", ")}${blockers.length > 5 ? ` and ${blockers.length - 5} more` : ""} ${blockers.length === 1 ? "has" : "have"} no build for Minecraft ${input.toVersion} yet, so the game update is on hold until ${blockers.length === 1 ? "it does" : "they do"} (your mods would crash the server on the new version).`,
  };
}

/** DB wrapper used by worker/game-update.ts before a version bump. Never throws. */
export async function modHoldForGameUpdate(serverId: string, variant: string | null, toVersion: string): Promise<{ hold: boolean; reason: string }> {
  try {
    const s = await db.modAutoUpdateSettings.findUnique({ where: { serverId }, select: { mode: true, holdGameUpdates: true } });
    const mode = s?.mode ?? "NOTIFY";
    if (mode === "OFF" || s?.holdGameUpdates === false) return { hold: false, reason: "mod checks off" };
    const rows = await db.serverMod.findMany({
      where: { serverId, status: { in: ["INSTALLED", "DISABLED"] } },
      select: { status: true, mod: { select: { name: true, gameVersions: true, versionRows: { select: { loaders: true, gameVersions: true }, take: 60, orderBy: { publishedAt: "desc" } } } } },
    });
    const mods = rows.filter((r) => r.status === "INSTALLED").map((r) => ({ name: r.mod.name, builds: r.mod.versionRows, projectVersions: r.mod.gameVersions }));
    if (!mods.length) return { hold: false, reason: "no mods" };
    const j = judgeGameBump({ variant, toVersion, mods });
    return { hold: j.hold, reason: j.reason };
  } catch (e) {
    console.error("[mod-autoupdate] game-hold check failed — not holding", e);
    return { hold: false, reason: "check failed" };
  }
}
