export const VALHEIM_CLIENT_OVERRIDES: Record<string, { required: boolean; why: string }> = {
  // Libraries every client-side Valheim mod is built on: players need them too.
  "valheimmodding-jotunn": { required: true, why: "Jötunn is a library the client-side halves of other mods load — players need the same version." },
  "denikson-bepinexpack_valheim": { required: true, why: "BepInEx is the mod loader itself; every player using mods needs it." },
  // Content mods: new items/pieces exist only if the player's game has them too.
  "randyknapp-epicloot": { required: true, why: "Epic Loot adds items and loot tables — players need the same version." },
  "advize-planteverything": { required: true, why: "Adds build pieces; players need the same version to place and see them." },
  "jerekuusela-server_devcommands": { required: true, why: "Dev commands run on each player's game; the server half alone does nothing." },
  // Add server-only packages here ONLY after checking the package page says so
  // (docs/DOCUMENTATION.md Valheim KB: MaxPlayerCount/BetterNetworking are UNVERIFIED).
};

const SERVER_PLUGIN_SOURCES = new Set(["hangar", "spigotmc", "umod", "codefling", "rocketmod"]);
const PLUGIN_VARIANTS = new Set(["paper", "purpur", "spigot", "bukkit", "folia"]);

export function classifyClient(m: ClientInfo): ClientVerdict {
  const fam = m.family.toLowerCase();
  const variant = (m.variant ?? "").toLowerCase();
  const cats = (m.categories ?? []).map((c) => c.toLowerCase());

  if (fam === "valheim") {
    const id = m.key.replace(/^thunderstore:/, "").toLowerCase();
    const o = VALHEIM_CLIENT_OVERRIDES[id];
    if (o) return { required: o.required, reason: o.why, basis: "curated" };
    const serverTag = cats.includes("server-side");
    const clientTag = cats.includes("client-side");
    if (serverTag && !clientTag) return { required: false, reason: "Thunderstore lists it as Server-side only.", basis: "provider" };
    if (clientTag && !serverTag) return { required: true, reason: "Thunderstore lists it as Client-side — players must have the same version.", basis: "provider" };
    return {
      required: true,
      reason: "Valheim gameplay mods have to be the same version on the server and on every player's game, or Valheim refuses the connection.",
      basis: "heuristic",
    };
  }

  if (fam === "minecraft") {
    if (SERVER_PLUGIN_SOURCES.has(m.source) || PLUGIN_VARIANTS.has(variant)) {
      return { required: false, reason: "Server plugin — players join with an unmodified game.", basis: "heuristic" };
    }
    const cs = (m.clientSide ?? "").toLowerCase();
    if (cs === "required") return { required: true, reason: "Modrinth: client_side = required — players need the same mod.", basis: "provider" };
    if (cs === "optional") return { required: false, reason: "Modrinth: client_side = optional — players can join without it.", basis: "provider" };
    if (cs === "unsupported") return { required: false, reason: "Modrinth: server-side only.", basis: "provider" };
    if (cats.includes("datapacks") || cats.includes("datapack")) return { required: false, reason: "Datapacks run on the server only.", basis: "heuristic" };
    return { required: null, reason: "The source doesn't say whether players need it.", basis: "unknown" };
  }

  if (fam === "factorio") {
    return { required: true, reason: "Factorio mods must match on every player — the game offers to download them when joining.", basis: "heuristic" };
  }
  if (fam === "rust" || fam === "cs2") {
    return { required: false, reason: "Server-side plugin — players join with an unmodified game.", basis: "heuristic" };
  }
  return { required: null, reason: "Not known for this game.", basis: "unknown" };
}

