type Payload = { trigger?: string; apply?: boolean; checkOnly?: boolean; by?: string | null };

export async function gameModAutoUpdate(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("mod auto-update: job has no serverId");
  const p = (job.payload ?? {}) as Payload;
  const trigger = p.trigger === "manual" || p.trigger === "game-update" ? p.trigger : "sweep";
  const manualApply = trigger === "manual" && p.apply === true;
  const server = await loadServer(job.serverId);
  if (!server) return;
  const family = familyFor(server);
  const installer = family ? ENGINE_INSTALLERS[family] : null;
  const env = envConfig();
  const step = (text: string, pct: number) => db.job.update({ where: { id: job.id }, data: { step: text.slice(0, 180), progress: Math.max(0, Math.min(99, pct)) } }).catch(() => {});

  if (!family || !installer) {
    await record(server.id, trigger, "NOOP", "Mod updates aren't available for this game (its mods are updated by the game itself, or there is no one-click mod support yet).");
    return;
  }
  if (server.status !== "RUNNING") {
    await record(server.id, trigger, "DEFERRED", "The server isn't running — checked again later.");
    return;
  }
  if (!env.realGuests) {
    await record(server.id, trigger, "DEFERRED", "One-click mod changes aren't enabled for this game yet, so the server wasn't checked.");
    await settle(server.id, { lastCheckAt: new Date(), lastStatus: "DEFERRED", lastDetail: "mod engine not enabled" });
    return;
  }

  let guest: GuestFs | null = null;
  let ssh: SshGuestFs | null = null;
  try {
    await step("Reading your server's mods", 5);
    if (env.sandbox) {
      const local = new LocalGuestFs(sandboxGuestRoot(server.id));
      await seedSandboxGuest(local, family, server.gameVariant ?? null);
      guest = local;
    } else {
      ssh = await SshGuestFs.open(server as never);
      guest = ssh;
    }
    await runFor(job, server, family, installer, guest, { trigger, manualApply, checkOnly: p.checkOnly === true, step });
  } finally {
    ssh?.close();
  }
}

