/** Presets offered for a family right now (env-flag gated ones hidden unless on). */
export function presetsFor(family: string, env: Record<string, string | undefined> = process.env): GamePreset[] {
  return GAME_PRESETS.filter((p) => p.family === family && (!p.flag || env[p.flag] === "1"));
}

/** A preset by id, only if it belongs to `family` and is currently offered. */
export function presetById(family: string, id: unknown, env: Record<string, string | undefined> = process.env): GamePreset | null {
  if (typeof id !== "string") return null;
  return presetsFor(family, env).find((p) => p.id === id) ?? null;
}

/** The marker key under which an order records its preset in Server.gameConfig. */
export const PRESET_MARKER = "_preset";
/** Set by worker/preset-mods.ts once every mod of the preset has been tried. */
export const PRESET_MODS_DONE_MARKER = "_presetModsDone";

/** The slice of a preset the browser needs (no evidence strings, no flags). */
export type PresetOption = Pick<GamePreset, "id" | "label" | "tagline" | "description" | "badge" | "variant" | "values" | "clientNote"> & {
  mods: { name: string; clientRequired: boolean }[];
};

export function presetOptionsFor(family: string, env: Record<string, string | undefined> = process.env): PresetOption[] {
  return presetsFor(family, env).map((p) => ({
    id: p.id,
    label: p.label,
    tagline: p.tagline,
    description: p.description,
    badge: p.badge,
    variant: p.variant,
    values: p.values,
    clientNote: p.clientNote,
    mods: (p.mods ?? []).map((m) => ({ name: m.name, clientRequired: m.clientRequired })),
  }));
}
