export function GameSettings({
  serverId,
  schema,
  variant: initialVariant,
  values: initialValues,
  disabled,
  canApply,
  gameState,
}: {
  serverId: string;
  schema: FamilySchema;
  variant: string;
  values: Values;
  disabled?: boolean;
  /** Whether the worker can actually WRITE these to the game server. */
  canApply: boolean;
  /**
   * The game's runtime state (lib/game-runtime.ts GameRuntimeState, or
   * "vm_off"). Decides whether "Apply & restart" is offered and what we
   * promise about the run state — a stopped server is never started by a save.
   */
  gameState?: string;
}) {
  const router = useRouter();
  const [variant, setVariant] = useState(initialVariant);
  const [values, setValues] = useState<Values>(initialValues);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const [initial] = useState(() => ({ variant: initialVariant, values: initialValues }));
  const gameUp = gameState === "online" || gameState === "unverified" || gameState === "starting" || gameState === "not_responding" || gameState === "unknown";
  const stopped = gameState === "stopped" || gameState === "game_stopped" || gameState === "crashed" || gameState === "vm_off";
  // Any changed field (or server type) that only takes effect on a restart.
  const restartNeeded = useMemo(() => {
    if (variant !== initial.variant) return true;
    // A family with per-field live apply (Project Zomboid): its admin password applies on
    // save with its own short restart, and the other fields never apply on a restart either,
    // so neither is a "restart later" change.
    if (LIVE_ONLY_FAMILIES.has(schema.family)) return false;
    return schema.fields.some((f) => f.phase === "deploy" && values[f.key] !== initial.values[f.key]) ||
      // Minecraft has no working live (RCON) push on this image, so every change waits for a restart.
      (schema.family === "minecraft" && schema.fields.some((f) => values[f.key] !== initial.values[f.key]));
  }, [variant, values, initial, schema]);

  // Fields grouped by their `group` heading, preserving declaration order.
  const groups = useMemo(() => {
    const map = new Map<string, ConfigField[]>();
    for (const f of schema.fields) {
      if (!map.has(f.group)) map.set(f.group, []);
      map.get(f.group)!.push(f);
    }

