  const envMap = await readContainerEnv(conn, RUST_CONTAINER);
  if (!envMap) {
    return { ok: false, applied: [], notes: [`Could not find the "${RUST_CONTAINER}" container — nothing was changed.`] };
  }

  const applied: string[] = [];
  const notes: string[] = [];
  // Server type -> Oxide switch (2026-10-02). Same diff-guard as Valheim's
  // BEPINEX: only recreate when the container's own env differs. `carbon` has no
  // switch on this image, so it is neither enabled nor treated as "vanilla":
  // a server already on it is left exactly as it is.
  if (gameVariant === "oxide" || gameVariant === "vanilla") {
    const wantsOxide = gameVariant === "oxide";
    const hasOxide = envMap.get("RUST_OXIDE_ENABLED") === "1";
    if (wantsOxide !== hasOxide) {
      for (const [k, val] of Object.entries(RUST_OXIDE_ENV)) envMap.set(k, wantsOxide ? val : "0");
      applied.push(wantsOxide ? "oxide-enabled" : "oxide-disabled");
      if (wantsOxide) notes.push("Oxide is installing on this restart (a one-time download). Install plugins from the Mods tab once the server is back.");
    }
  }
