lib/modsync/registry.ts:14:export const PROVIDERS: Provider[] = [modrinth, hangar, ficsit, factorio, thunderstore, spigotmc, umod, github, steamWorkshop, modio];
/**
 * uMod (Oxide / Carbon plugins) — Rust, 7 Days to Die (+ other uMod games we host). Reads ONLY the open
 * static data uMod publishes for third parties on `assets.umod.org`:
 *   /plugins/manifest.json      one object of ~1,700 plugins {Key: {title, description, icon, tags, url, games[]}}
 *   /plugins/<Key>.json         license, repository, maintainers, branches.master.<ver>.{download_url, checksum(sha1), requires, suggests}
 * uMod's developer docs call these endpoints public and say third parties may host a mirror of the manifest.
 * We NEVER request umod.org itself (its robots.txt/ToS sit behind a Cloudflare challenge we must not bypass)
 * and never scrape HTML.
 *
 * Policy: METADATA + LINK-THROUGH (some plugins are "MIT with distribution exclusivity for uMod.org"),
 * never mirrored; the Rust installer fetches the .cs from assets.umod.org at install time.
 * Plugins tagged `broken` in the manifest are skipped. Rate 30/min, ETag-free (manifest is a 24 h cached
 * 700 KB file); per-plugin files are only re-read in a `full` pass or when we have never seen the plugin.
 */
import type { NormalizedDep, NormalizedMod, NormalizedVersion, Provider, SliceResult, SyncContext } from "../types";

const ASSETS = "https://assets.umod.org/plugins";

/** uMod game slug -> our gameFamily (only games we host). */
export const UMOD_GAMES: Record<string, string> = { rust: "rust", "7-days-to-die": "sdtd", "the-forest": "theforest" };

export interface UmManifestEntry { title?: string; description?: string; icon?: string; tags?: string | string[]; maintainers?: unknown; url?: string; games?: string[] }
export interface UmBranchVersion { formatted?: string; download_url?: string; checksum?: string; published_at?: string; requires?: Record<string, string | unknown>; suggests?: Record<string, string | unknown> }
export interface UmPlugin {
  name?: string; title?: string; description?: string; url?: string; published_at?: string; icon?: string; tags?: string[]; type?: string; repository?: string;
  watchers?: { count?: number }; license?: { name?: string | null; url?: string | null } | null;
  games?: Record<string, { name?: string }>; maintainers?: Record<string, { name: string; url?: string; icon?: string | null; donate_url?: string | null }>;
  branches?: { master?: Record<string, UmBranchVersion> };
}

const UM_LICENSE: Record<string, string> = { gpl3: "GPL-3.0", gpl2: "GPL-2.0", mit: "MIT", apache2: "Apache-2.0", lgpl3: "LGPL-3.0", agpl3: "AGPL-3.0", bsd3: "BSD-3-Clause", bsd2: "BSD-2-Clause", cc0: "CC0-1.0", mpl2: "MPL-2.0", unlicense: "Unlicense" };
export const umodLicense = (l: string | null | undefined) => (l ? UM_LICENSE[l.toLowerCase()] ?? l : null);
const slugOf = (url: string | undefined, key: string) => /\/plugins\/([^/?#]+)/.exec(url ?? "")?.[1] ?? key.toLowerCase();
