/**
 * Pure planner for "install the mods of the preset this server was ordered
 * with" (worker/preset-mods.ts runs it). One mod at a time, because the mod
 * queue allows a single job in flight per server (lib/mods/queue.ts).
 *
 * A mod is "settled" once it is installed/disabled (done), failed (tried once,
 * never retried automatically) or missing from the catalogue (skipped with the
 * reason shown to the customer). Only when every mod is settled is the preset
 * marked done, so the customer gets exactly one summary.
 */
import type { PresetMod } from "./game-presets";

export type CatalogHit = { id: string; active: boolean; upstreamOk: boolean; paid?: boolean } | null;
export type ServerModRow = { sourceId: string; status: string };

export type PresetModPlan = {
  /** The one mod to enqueue now, or null. */
  next: { mod: PresetMod; catalogId: string } | null;
  /** All mods settled: write the done marker and tell the customer. */
  done: boolean;
  installed: string[];
  failed: string[];
  skipped: { name: string; reason: string }[];
};

const BUSY = new Set(["INSTALLING", "UPDATING", "DISABLING", "ENABLING", "REMOVING"]);

export function planPresetMods(mods: PresetMod[], rows: ServerModRow[], catalog: Map<string, CatalogHit>): PresetModPlan {
  const bySource = new Map(rows.map((r) => [r.sourceId, r.status]));
  const plan: PresetModPlan = { next: null, done: false, installed: [], failed: [], skipped: [] };
  let pending = 0;
  for (const m of mods) {
    const st = bySource.get(m.sourceId);
    if (st === "INSTALLED" || st === "DISABLED") { plan.installed.push(m.name); continue; }
    if (st === "FAILED") { plan.failed.push(m.name); continue; }
    if (st && BUSY.has(st)) { pending++; continue; }
    const hit = catalog.get(m.sourceId) ?? null;
    if (!hit) { plan.skipped.push({ name: m.name, reason: "it isn't in our mod catalogue right now" }); continue; }
    if (!hit.active || !hit.upstreamOk) { plan.skipped.push({ name: m.name, reason: "its author has withdrawn or deprecated it" }); continue; }
    if (hit.paid) { plan.skipped.push({ name: m.name, reason: "it is a paid mod" }); continue; }
    pending++;
    if (!plan.next) plan.next = { mod: m, catalogId: hit.id };
  }
  plan.done = pending === 0;
  return plan;
}

/** The customer-facing summary written when a preset's mods are settled. */
export function presetModsSummary(label: string, plan: PresetModPlan): string {
  const parts: string[] = [];
  if (plan.installed.length) parts.push(`Installed: ${plan.installed.join(", ")}.`);
  if (plan.failed.length) parts.push(`Couldn't install: ${plan.failed.join(", ")} (you can retry from the Mods tab).`);
  if (plan.skipped.length) parts.push(`Skipped: ${plan.skipped.map((s) => `${s.name} (${s.reason})`).join("; ")}.`);
  if (!parts.length) parts.push("Nothing needed installing.");
  return `Your "${label}" setup is finished. ${parts.join(" ")}`;
}
EOF
