cd /opt/nxeon-wt-g5; cat > worker/preset-mods.ts <<'EOF'
/**
 * Install the mods of the preset a game server was ordered with, after its
 * first boot (lib/game-presets.ts, lib/preset-mods.ts).
 *
 * Registered on the SweepRunner as "preset-mods" (worker/index.ts). INERT unless
 * BOTH ENABLE_PRESET_MODS=1 and ENABLE_REAL_GAMEMODS=1 are set: it writes mods
 * onto customer servers, which is exactly what ENABLE_REAL_GAMEMODS already
 * gates everywhere else.
 *
 * Per sweep, per server (never while any job is queued/running on it):
 *   1. the server was provisioned (a DONE PROVISION job) and, when its server
 *      type needed a GAME_CONFIG apply (Valheim BepInEx), that apply is DONE;
 *   2. its game is online (GameRuntime.state) so the mod folders exist;
 *   3. plan (lib/preset-mods.ts) -> enqueue ONE install through the normal mod
 *      queue (lib/mods/queue.ts), so audit rows, locks and the Mods tab all
 *      behave exactly as for a customer's own click;
 *   4. when every mod is settled: one restart so the game loads them (only if
 *      something was installed), one customer notification, and the
 *      `_presetModsDone` marker so this never runs again for the server.
 * Only servers created in the last 14 days are considered, so enabling the
 * flag never touches an old server.
 */
import type { Prisma } from "@prisma/client";
import { db } from "../lib/db";
import { GAME_PRESETS, PRESET_MARKER, PRESET_MODS_DONE_MARKER } from "../lib/game-presets";
import { planPresetMods, presetModsSummary, type CatalogHit } from "../lib/preset-mods";
import { enqueueModOp } from "../lib/mods/queue";
import { familyFor, schemaFor } from "../lib/game-config";

const INFLIGHT = ["QUEUED", "RUNNING"] as const;
const WINDOW_MS = 14 * 24 * 3600_000;

export function presetModsEnabled(env: NodeJS.ProcessEnv = process.env): boolean {
  return env.ENABLE_PRESET_MODS === "1" && env.ENABLE_REAL_GAMEMODS === "1";
}

let running = false;

export async function presetModsSweep(): Promise<{ considered: number; enqueued: number }> {
  if (!presetModsEnabled() || running) return { considered: 0, enqueued: 0 };
  running = true;
  let considered = 0;
  let enqueued = 0;
  try {
    const servers = await db.server.findMany({
      where: { status: "RUNNING", createdAt: { gt: new Date(Date.now() - WINDOW_MS) }, gameConfig: { not: undefined } },
      include: { osTemplate: true, gamePlan: true, gameRuntime: { select: { state: true } }, mods: { include: { mod: { select: { sourceId: true } } } } },
      take: 200,
    });
    for (const s of servers) {
      const cfg = (s.gameConfig ?? {}) as Record<string, unknown>;
      const presetId = cfg[PRESET_MARKER];
      if (typeof presetId !== "string" || cfg[PRESET_MODS_DONE_MARKER]) continue;
      const family = familyFor(s);
      const preset = GAME_PRESETS.find((p) => p.id === presetId && p.family === family);
      if (!preset?.mods?.length) continue;
      considered++;
      if (s.gameRuntime?.state !== "online") continue;
      if ((await db.job.count({ where: { serverId: s.id, status: { in: [...INFLIGHT] } } })) > 0) continue;
      if (!(await db.job.findFirst({ where: { serverId: s.id, type: "PROVISION", status: "DONE" }, select: { id: true } }))) continue;
      const schema = schemaFor(family);
      const needsConfigApply = !!schema && !!s.gameVariant && s.gameVariant !== schema.defaultVariant;
      if (needsConfigApply && !(await db.job.findFirst({ where: { serverId: s.id, type: "GAME_CONFIG", status: "DONE" }, select: { id: true } }))) continue;

      const catalog = new Map<string, CatalogHit>();
      for (const m of preset.mods) {
        const row = await db.gameMod.findFirst({
          where: { gameFamily: family!, source: m.source, sourceId: m.sourceId },
          select: { id: true, active: true, upstreamOk: true, paid: true },
        });
        if (row) catalog.set(m.sourceId, row);
        else if (m.source === "steam_workshop") {
          // Workshop items are metadata + link-through: the row is created from the preset's own facts.
          const created = await db.gameMod.create({
            data: {
              gameFamily: family!, name: m.name, slug: `${family}-${m.sourceId}`, category: "QoL", source: m.source, sourceId: m.sourceId,
              url: `https://steamcommunity.com/sharedfiles/filedetails/?id=${m.sourceId}`,
            },
            select: { id: true, active: true, upstreamOk: true, paid: true },
          }).catch(() => null);
          if (created) catalog.set(m.sourceId, created);
        }
      }
      const rows = s.mods.map((r) => ({ sourceId: r.mod.sourceId ?? "", status: r.status }));
      const plan = planPresetMods(preset.mods, rows, catalog);

      if (plan.next) {
        const r = await enqueueModOp(s.id, plan.next.catalogId, "install", { userId: s.userId, slug: plan.next.mod.sourceId });
        if (r.ok) enqueued++;
        continue;
      }
      if (!plan.done) continue;

      const fresh = await db.server.findUnique({ where: { id: s.id }, select: { gameConfig: true } });
      const next = { ...((fresh?.gameConfig ?? {}) as Record<string, unknown>), [PRESET_MODS_DONE_MARKER]: new Date().toISOString() };
      await db.server.update({ where: { id: s.id }, data: { gameConfig: next as Prisma.InputJsonValue } });
      const summary = presetModsSummary(preset.label, plan);
      await db.notification
        .create({ data: { userId: s.userId, title: `${s.hostname}: your ${preset.label} setup is ready`, body: summary, href: `/dashboard/servers/${s.id}?tab=mods` } })
        .catch(() => {});
      if (plan.installed.length) {
        await db.job
          .create({ data: { type: "GAME_POWER", serverId: s.id, payload: { action: "restart", announce: false, source: "provision" } } })
          .catch(() => {});
      }
    }
  } finally {
    running = false;
  }
  return { considered, enqueued };
}
EOF
