/**
 * "Do your players need this mod too?" at install time (prd-032).
 *
 * Ticket 12 (2026-09-24): a Valheim mod installed server-side locked out every
 * friend without the client copy. The mod browser already shows a chip when the
 * catalogue row carries a client flag, but Thunderstore rows carry none, so for
 * Valheim the answer was silently "unknown". This reuses the one classifier the
 * auto-updater already trusts (lib/mod-autoupdate/client-side.ts: curated list,
 * then the provider's own flag, then a conservative per-game heuristic) so the
 * install dialog, the cards and the auto-updater can never disagree.
 */
import { classifyClient, type ClientVerdict } from "./mod-autoupdate/client-side";

export type ClientWarning = { required: boolean | null; reason: string; basis: ClientVerdict["basis"] };

type ModLike = {
  gameFamily: string;
  source: string;
  sourceId: string | null;
  name: string;
  categories?: string[] | null;
  clientSide?: string | null;
  serverSide?: string | null;
};

export function clientWarningFor(m: ModLike, variant: string | null): ClientWarning {
  const v = classifyClient({
    family: m.gameFamily,
    source: m.source,
    key: m.sourceId ?? m.name,
    name: m.name,
    variant,
    clientSide: m.clientSide ?? null,
    serverSide: m.serverSide ?? null,
    categories: m.categories ?? [],
  });
  return { required: v.required, reason: v.reason, basis: v.basis };
}
