/**
 * Wave 11 (2026-09-24) — DayZ.
 *
 * Blocked since Wave 4 (see lib/games.ts's GAME_DISPLAY comment and
 * prisma/seed-wave9-games.ts's own header, which both name DayZ as
 * "researched but not scaffolded") on a real problem: unlike every other
 * SteamCMD-installed family in this catalog, DayZ's dedicated-server depot
 * (Steam app 223350) REJECTS anonymous login — confirmed against multiple
 * independent hosting guides and the DayZ Steam community's own setup
 * guides, not assumed. The account doing the download must genuinely own
 * DayZ (app 221100).
 *
 * Solved for real, not just documented again, in two parts:
 *
 *   1. lib/dayz-steam.ts — a dedicated, Nxeon-owned, download-only Steam
 *      account (never a customer's), Steam Guard deliberately disabled on
 *      it (the standard, explicitly-documented practice for exactly this
 *      automation scenario — see that file's own doc comment for the full
 *      reasoning and the alternative that was NOT chosen). Its credentials
 *      (DAYZ_STEAM_USERNAME/DAYZ_STEAM_PASSWORD) are substituted into this
 *      template's `-e USERNAME=/-e PASSWRD=` placeholders below by
 *      worker/index.ts:buildCloudInit, the same applyGameControlSecrets
 *      mechanism Palworld/Rust/CS2 already use for their own per-server
 *      secrets — just a fixed shared value here, not freshly generated.
 *      lib/game-order.ts refuses new DayZ orders outright while that
 *      account doesn't exist yet (dayzSteamConfigured() === false) — an
 *      honest "not available yet," never a checkout that appears to succeed
 *      and then crash-loops on SteamCMD's own anonymous-login rejection.
 *
 *   2. lib/game-config.ts's DAYZ schema + worker/game-config.ts's applyDayZ
 *      — serverDZ.cfg is genuinely file-based (Bohemia's own `key = value;`
 *      cfg syntax, not a docker env var), so a customer's chosen settings
 *      reach the live server through the SAME real-apply SFTP
 *      read-modify-write path already verified live for Minecraft's
 *      server.properties — see that schema's own comment for exactly what
 *      was and wasn't verified (no live box to test against here either).
 *
 * Docker image: `ich777/steamcmd:dayz` — ich777 is already a trusted
 * publisher in this exact catalog (gmod uses `ghcr.io/ich777/steamcmd:
 * garrysmod`, cs16-shaped families use the same steamcmd wrapper family).
 * Its README (raw.githubusercontent.com/ich777/docker-steamcmd-server/dayz/
 * README.md, fetched live 2026-09-24) documents GAME_ID/GAME_PORT/UID/GID/
 * VALIDATE/USERNAME/PASSWRD as real env vars — but its OWN documented
 * default (GAME_ID=1042420) is the EXPERIMENTAL branch, which needs the
 * experimental-branch CLIENT to connect ("Keep in mind that you have to
 * connect with the experimental branch Client to this Docker container!") —
 * wrong for a real product, whose customers run the normal DayZ client.
 * GAME_ID is overridden below to 223350, the real STABLE dedicated-server
 * depot. UNVERIFIED: whether this image's internal launch script (built
 * around the experimental branch's own directory layout) behaves identically
 * once pointed at the stable depot instead — no Steam account exists in this
 * environment to actually run steamcmd and find out. This is the single
 * biggest remaining unknown in this whole family; flagged, not guessed past.
 *
 * The README also documents a genuine footgun `worker/game-config.ts`'s
 * `applyDayZ` already accounts for: "changes to the serverDZ.cfg in the main
 * directory take no effect, you have to edit the file .../saves/
 * serverDZ.cfg".
 *
 * Ports: 2302-2306/udp — the commonly-documented safe range across DayZ
 * hosting guides (2302 game, 2305 steamQueryPort per the real reference
 * serverDZ.cfg used in test/dayz-config.test.ts, the rest as headroom for
 * BattlEye/misc) — NOT individually verified port-by-port against this
 * specific image (no live box). lib/games.ts's GAME_PORT stays the single
 * real, universally-documented 2302/udp join port for health-checking.
 *
 * Run: cd /opt/nxeon-staging && npx tsx prisma/seed-wave11-dayz.ts   (idempotent)
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type Template = { family: string; name: string; setupScript: string; minRamMB: number; minDiskGB: number };

const TEMPLATES: Template[] = [
  {
    family: "dayz",
    name: "DayZ Server",
    minRamMB: 6144,
    minDiskGB: 20,
    setupScript:
      `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/dayz/steamcmd /opt/dayz/serverfiles && docker run -d --name dayz --restart unless-stopped -p 2302-2306:2302-2306/udp -e GAME_ID='223350' -e GAME_PORT='2302' -e UID='99' -e GID='100' -e VALIDATE='tr
  },
];

type TierSpec = { gameFamily: string; name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number; priceCents: number; featured?: boolean };

const TIERS: TierSpec[] = [
  // DayZ — priced in line with Conan Exiles (same rough RAM/disk footprint,
  // same "brutal open-world survival" audience), capped at DayZ's real
  // official 60-player ceiling (see lib/game-config.ts's maxPlayers field)
  // rather than Conan's 70.
  { gameFamily: "dayz", name: "DayZ — 6 GB / 20 players", ramMB: 6144, cpuCores: 2, diskGB: 20, slots: 20, priceCents: 1499 },
  { gameFamily: "dayz", name: "DayZ — 8 GB / 40 players", ramMB: 8192, cpuCores: 3, diskGB: 30, slots: 40, priceCents: 2299, featured: true },
  { gameFamily: "dayz", name: "DayZ — 12 GB / 60 players", ramMB: 12288, cpuCores: 4, diskGB: 40, slots: 60, priceCents: 3299 },
];

async function main() {
  const templateIdByFamily = new Map<string, string>();
  let sort = 140;
  for (const t of TEMPLATES) {
    const os = await db.osTemplate.upsert({
      where: { slug: t.family },
      create: {
        slug: t.family, name: t.name, category: "APPLICATION", family: t.family, version: "", logo: t.family,
        vmid: 9000, baseVmid: 9000, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB,
        licenseRequired: false, featured: false, sortOrder: sort++, active: true,
      },
      update: { name: t.name, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB, active: true },
    });
    templateIdByFamily.set(t.family, os.id);
    console.log(`  osTemplate ${t.family.padEnd(16)} → ${os.id}`);
  }

  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
  const largest = plans[plans.length - 1];

  let created = 0, updated = 0;
  const sortByGame = new Map<string, number>();
  for (const spec of TIERS) {
    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
    const osId = templateIdByFamily.get(spec.gameFamily) ?? null;
    const sortOrder = sortByGame.get(spec.gameFamily) ?? 0;
    sortByGame.set(spec.gameFamily, sortOrder + 1);
    const data = {
      gameFamily: spec.gameFamily, name: spec.name, ramMB: spec.ramMB, cpuCores: spec.cpuCores, diskGB: spec.diskGB,
      slots: spec.slots, priceCents: spec.priceCents, termMonths: 1, basePlanId: basePlan.id, osTemplateId: osId,
      featured: spec.featured ?? false, active: true, sortOrder,
    };
    const existing = await db.gamePlan.findFirst({ where: { gameFamily: spec.gameFamily, name: spec.name } });
    if (existing) { await db.gamePlan.update({ where: { id: existing.id }, data }); updated++; }
    else { await db.gamePlan.create({ data }); created++; }
    console.log(`  plan ${spec.name.padEnd(38)} base=${basePlan.name}`);
  }
  console.log(`\nWave 11: ${TEMPLATES.length} OsTemplate, GamePlans ${created} created / ${updated} updated.`);
