/**
 * Wave 12 (2026-10-02) — Arma 3. Growth batch G5, item prd-025.
 *
 * SCAFFOLD, NOT A PRODUCT YET. Both the OsTemplate and every GamePlan are seeded
 * INACTIVE (`active: false`): the deploy wizard only offers a family with an
 * active plan, so nothing here is orderable until the owner runs the real
 * provision test in docs/DOCUMENTATION.md ("Growth batch G5 -> Arma 3") and then
 * flips them on. No real provision was possible from the build session, so every
 * statement below about how the image behaves is UNVERIFIED.
 *
 * Image: `gameservermanagers/gameserver:arma3` — LinuxGSM's own container for the
 * `arma3server` (Docker Hub tag exists, last pushed 2026-09-26, ~430 MB). Chosen
 * over `ich777/steamcmd:arma3` (last pushed 2024-12-19) and the Pterodactyl egg
 * image (`ghcr.io/parkervcp/games:arma3`, which expects the egg's own startup
 * wrapper, not plain `docker run`). Server files + LinuxGSM config live under
 * `/data` in the container; mounted at /opt/arma3 so the files tab and backups
 * (dataRoots in lib/game-control.ts) see them.
 *
 * Ports: 2302-2306/udp (Bohemia wiki: game port 2302 plus the Steam query / voice
 * block). lib/games.ts GAME_PORT stays 2302/udp for the readiness check.
 *
 * Known unknowns the verification run must answer:
 *   1. Does the LinuxGSM image run as root or uid 1000? (chown below assumes 1000.)
 *   2. Does `arma3server install` work with anonymous SteamCMD login for the server
 *      depot (app 233780)? Workshop mods need a logged-in Steam account that owns
 *      Arma 3 (same class of problem as DayZ, lib/dayz-steam.ts) — mods are NOT
 *      offered for this family until that is solved.
 *   3. Cold-start time (the first start downloads the server, ~3 GB).
 *   4. CPU: Arma 3's server is single-thread bound; the tiers below are sized by
 *      RAM and slots, but the REAL limit is per-core clock on the node.
 *   5. Bohemia's commercial-hosting terms — UNVERIFIED, owner must read them before
 *      activating (same legal-sensitivity rule as Hytale/FiveM).
 *
 * Pricing is a placeholder for the owner to set; nothing is visible until activated.
 *
 * Run: cd /opt/nxeon-staging && npx tsx prisma/seed-wave12-arma3.ts   (idempotent)
 * Activate (owner, after verification):
 *   UPDATE "OsTemplate" SET active=true WHERE slug='arma3';
 *   UPDATE "GamePlan" SET active=true WHERE "gameFamily"='arma3';
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

const SETUP =
  "curl -fsSL https://get.docker.com | sh && mkdir -p /opt/arma3 && chown -R 1000:1000 /opt/arma3 && " +
  "docker run -d --name arma3 --restart unless-stopped --stop-timeout 60 " +
  "-p 2302-2306:2302-2306/udp -v /opt/arma3:/data gameservermanagers/gameserver:arma3";

type TierSpec = { name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number; priceCents: number; featured?: boolean };
const TIERS: TierSpec[] = [
  { name: "Arma 3 — 4 GB / 16 players", ramMB: 4096, cpuCores: 2, diskGB: 40, slots: 16, priceCents: 1299 },
  { name: "Arma 3 — 8 GB / 32 players", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 32, priceCents: 2299, featured: true },
  { name: "Arma 3 — 12 GB / 64 players", ramMB: 12288, cpuCores: 4, diskGB: 60, slots: 64, priceCents: 3499 },
];

async function main() {
  const os = await db.osTemplate.upsert({
    where: { slug: "arma3" },
    create: {
      slug: "arma3", name: "Arma 3 Server", category: "APPLICATION", family: "arma3", version: "", logo: "arma3",
      vmid: 9000, baseVmid: 9000, setupScript: SETUP, minRamMB: 4096, minDiskGB: 40,
      licenseRequired: false, featured: false, sortOrder: 150, active: false,
    },
    // NEVER flips `active` on an existing row: activation is the owner's decision.
    update: { name: "Arma 3 Server", setupScript: SETUP, minRamMB: 4096, minDiskGB: 40 },
  });
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
  const largest = plans[plans.length - 1];
  let sortOrder = 0;
  for (const t of TIERS) {
    const basePlan = plans.find((p) => p.ramMB >= t.ramMB) ?? largest;
    const data = {
      gameFamily: "arma3", name: t.name, ramMB: t.ramMB, cpuCores: t.cpuCores, diskGB: t.diskGB, slots: t.slots,
      priceCents: t.priceCents, termMonths: 1, basePlanId: basePlan.id, osTemplateId: os.id, featured: t.featured ?? false, sortOrder: sortOrder++,
    };
    const existing = await db.gamePlan.findFirst({ where: { gameFamily: "arma3", name: t.name } });
    // Same rule: an existing row keeps whatever `active` the owner set.
    if (existing) await db.gamePlan.update({ where: { id: existing.id }, data });
    else await db.gamePlan.create({ data: { ...data, active: false } });
    console.log(`  plan ${t.name} (inactive until activated)`);
  }
  console.log("Arma 3 scaffold seeded INACTIVE. Run the verification in docs/DOCUMENTATION.md before activating.");
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());
