/**
 * URL fragment for each family, reused verbatim from its existing dedicated
 * page's own folder name (app/(marketing)/<fragment>-server-hosting) so a
 * combo slug like "germany-<fragment>-server-hosting" reads consistently
 * with the flagship page it links to in `related`, and so nothing here
 * invents a second naming scheme that could drift from the first.
 */
export const GAME_URL_SLUG: Record<GameFamily, string> = {
  minecraft: "minecraft",
  bedrock: "minecraft-bedrock",
  valheim: "valheim",
/**
 * One factual, well-known sentence per family — genre/premise plus its real
 * modding or community ecosystem — used to make each game's prose actually
 * differ from its siblings (not just a swapped noun). General public
 * knowledge about each title, not a claim about Nxeon's own operation of it.
 */
const GAME_FLAVOR: Record<GameFamily, string> = {
  minecraft: "a sandbox building and survival game with an enormous Spigot/Paper plugin and Forge/Fabric mod ecosystem",
  bedrock: "the cross-play Bedrock Edition of Minecraft (console, mobile, Windows) with its own Add-Ons behavior-pack ecosystem",
  valheim: "a Viking-themed survival-exploration game with a large BepInEx mod scene",
  rust: "a hardcore multiplayer survival game built around base-building, raiding and Oxide/uMod plugins",
  blurb: string;
  /** Short honest note — access path, maturity caveat, etc. */
  note: string;
};

export const MOD_INFO: Record<GameFamily, ModInfo> = {
  minecraft: {
    platform: "Forge, Fabric, NeoForge & Paper/Spigot",
    blurb: "Every major Java Edition loader and plugin API is supported — swap the server jar and go.",
    note: "One-click install from the dashboard's Mods tab — the right build for your loader and version, with its dependencies. Anything else: upload via SFTP or the file manager.",
  },

