import { test } from "node:test";
import assert from "node:assert/strict";
import { GAME_PRESETS, presetsFor, presetById, presetOptionsFor } from "../lib/game-presets.ts";
import { schemaFor, validateConfig, isSelectableVariant, isValidVariant } from "../lib/game-config.ts";
import { planPresetMods, presetModsSummary } from "../lib/preset-mods.ts";

test("every preset names a real family, a selectable variant and valid field values", () => {
  for (const p of GAME_PRESETS) {
    const schema = schemaFor(p.family);
    assert.ok(schema, `${p.id}: unknown family`);
    const variant = p.variant ?? schema.orderDefaults?.variant ?? schema.defaultVariant;
    assert.ok(isValidVariant(p.family, variant), `${p.id}: variant ${variant}`);
    assert.ok(isSelectableVariant(p.family, variant), `${p.id}: variant ${variant} is flagged unavailable`);
    for (const k of Object.keys(p.values)) assert.ok(schema.fields.some((f) => f.key === k), `${p.id}: no field ${k}`);
    // SERVER_PASS is required for Valheim; the wizard supplies it, so validate with a stand-in.
    const res = validateConfig(p.family, { ...p.values, SERVER_PASS: "abcde12345" });
    assert.ok(res.ok, `${p.id}: ${res.ok ? "" : res.error}`);
  }
});

test("preset ids are unique and every mod has evidence and a plausible id", () => {
  const ids = new Set<string>();
  for (const p of GAME_PRESETS) {
    assert.ok(!ids.has(p.id));
    ids.add(p.id);
    for (const m of p.mods ?? []) {
      assert.ok(m.evidence.length > 20, `${p.id}/${m.name}: no evidence`);
      if (m.source === "steam_workshop") assert.match(m.sourceId, /^\d{6,}$/);
      if (m.source === "thunderstore") assert.match(m.sourceId, /^[A-Za-z0-9_]+-[A-Za-z0-9_]+$/);
    }
  }
});

test("Valheim new-order defaults are BepInEx + crossplay and existing-server defaults are unchanged", () => {
  const s = schemaFor("valheim")!;
  assert.equal(s.orderDefaults?.variant, "bepinex");
  assert.equal(s.orderDefaults?.values?.CROSSPLAY, true);
  // Retroactivity guard: a stored blank config / null variant must still mean vanilla + no crossplay.
  assert.equal(s.defaultVariant, "vanilla");
  assert.equal(s.fields.find((f) => f.key === "CROSSPLAY")?.default, false);
});

test("the Valheim Big group preset is hidden until its flag is on", () => {
  assert.ok(!presetsFor("valheim", {}).some((p) => p.id === "valheim-big-group"));
  assert.ok(presetsFor("valheim", { ENABLE_VALHEIM_BIG_GROUP_PRESET: "1" }).some((p) => p.id === "valheim-big-group"));
  assert.equal(presetById("valheim", "valheim-big-group", {}), null);
  assert.equal(presetById("valheim", 42 as unknown, {}), null);
  assert.equal(presetById("rust", "valheim-vanilla-plus", {}), null);
});

test("preset options for the browser carry only strings", () => {
  const opts = presetOptionsFor("valheim", {});
  assert.ok(opts.length >= 1);
  for (const o of opts) for (const v of Object.values(o.values)) assert.equal(typeof v, "string");
  assert.ok(!JSON.stringify(opts).includes("evidence"));
});

test("Rust: Carbon is flagged unavailable for new choices but an existing Carbon server keeps it", () => {
  assert.ok(!isSelectableVariant("rust", "carbon"));
  assert.ok(isSelectableVariant("rust", "carbon", "carbon"));
  assert.ok(isSelectableVariant("rust", "oxide"));
  assert.ok(isSelectableVariant("rust", "vanilla"));
});

test("planPresetMods installs one at a time, skips what is missing, and finishes once all are settled", () => {
  const mods = GAME_PRESETS.find((p) => p.id === "valheim-big-group")!.mods!;
  const cat = new Map([
    ["Azumatt-MaxPlayerCount", { id: "m1", active: true, upstreamOk: false }],
    ["tibijczyk-BetterNetworking_Valheim", { id: "m2", active: true, upstreamOk: true }],
  ]);
  let plan = planPresetMods(mods, [], cat);
  assert.equal(plan.next?.catalogId, "m2");
  assert.equal(plan.done, false);
  assert.deepEqual(plan.skipped.map((s) => s.name), ["MaxPlayerCount"]);
  plan = planPresetMods(mods, [{ sourceId: "tibijczyk-BetterNetworking_Valheim", status: "INSTALLING" }], cat);
  assert.equal(plan.next, null);
  assert.equal(plan.done, false);
  plan = planPresetMods(mods, [{ sourceId: "tibijczyk-BetterNetworking_Valheim", status: "INSTALLED" }], cat);
  assert.equal(plan.done, true);
  assert.match(presetModsSummary("Big group", plan), /Installed: BetterNetworking.*Skipped: MaxPlayerCount/);
  plan = planPresetMods(mods, [{ sourceId: "tibijczyk-BetterNetworking_Valheim", status: "FAILED" }], new Map());
  assert.equal(plan.done, true);
  assert.deepEqual(plan.failed, ["BetterNetworking"]);
});
