import { test } from "node:test";
import assert from "node:assert/strict";
import { judgeModHealth, decideHealthAction, healthSummary, healthSupported, nameForms } from "../lib/mod-health.ts";

const BEP_LOG = `
[Message:   BepInEx] BepInEx 5.4.2333 - valheim
[Info   :   BepInEx] Loading [Jotunn 2.20.3]
[Info   :   BepInEx] Loading [Server Side QoL 2.2.0]
[Error  :   BepInEx] Could not load [Old Mod 1.0.0] because it is missing dependencies
[Message:   BepInEx] Chainloader startup complete
`;

test("BepInEx: loaded by plugin name, errored by name, not-seen when the framework is up", () => {
  const r = judgeModHealth({
    family: "valheim",
    variant: "bepinex",
    log: BEP_LOG,
    mods: [
      { name: "ServersideQoL", key: "ArgusMagnus-ServersideQoL" },
      { name: "Jotunn", key: "ValheimModding-Jotunn" },
      { name: "Old Mod", key: "Someone-OldMod" },
      { name: "Silent Thing", key: "Author-SilentThing" },
    ],
  });
  const by = Object.fromEntries(r.verdicts.map((v) => [v.mod.name, v.status]));
  assert.deepEqual(by, { ServersideQoL: "loaded", Jotunn: "loaded", "Old Mod": "error", "Silent Thing": "not-seen" });
  assert.equal(r.overall, "warn");
  assert.equal(r.errored.length, 1);
  assert.equal(r.missing.length, 1);
});

test("BepInEx: no BepInEx output at all means unknown, never a failure", () => {
  const r = judgeModHealth({ family: "valheim", variant: "bepinex", log: "Game server connected", mods: [{ name: "Foo Bar Mod", key: "A-FooBarMod" }] });
  assert.equal(r.verdicts[0].status, "unknown");
  assert.equal(r.overall, "unknown");
  assert.deepEqual(decideHealthAction({ report: r, playersOnline: 0, alreadyRestartedForThisStart: false, autoPause: true, autoRestart: true }).kind, "none");
});

test("Oxide, Paper and TShock load lines", () => {
  const ox = judgeModHealth({ family: "rust", variant: "oxide", log: "[Oxide] Loading Oxide Core v2.0\nLoaded plugin Vanish v1.8.0 by Wulf\nError while compiling BrokenPlug: Foo.cs(3,1) : error CS1002", mods: [{ name: "Vanish", key: "vanish" }, { name: "BrokenPlug", key: "brokenplug" }] });
  assert.deepEqual(ox.verdicts.map((v) => v.status), ["loaded", "error"]);
  const pp = judgeModHealth({ family: "minecraft", variant: "paper", log: "[12:00:00 INFO]: [LuckPerms] Enabling LuckPerms v5.4.150\n[12:00:09 INFO]: Done (8.2s)!", mods: [{ name: "LuckPerms", key: "luckperms" }, { name: "EssentialsX", key: "essentialsx" }] });
  assert.deepEqual(pp.verdicts.map((v) => v.status), ["loaded", "not-seen"]);
  const ts = judgeModHealth({ family: "terraria", variant: null, log: "TShock 5.2 initialized\nPlugin Vote v1.0 (by Someone) initiated.", mods: [{ name: "Vote", key: "vote-plugin" }] });
  assert.equal(ts.verdicts[0].status, "loaded");
});

test("games without a readable per-mod line are unsupported", () => {
  assert.ok(!healthSupported("valheim", "vanilla"));
  assert.ok(!healthSupported("projectzomboid", "b42"));
  assert.ok(!healthSupported("minecraft", "fabric"));
  const r = judgeModHealth({ family: "projectzomboid", variant: "b42", log: "x", mods: [{ name: "Mod One", key: "1" }] });
  assert.equal(r.supported, false);
  assert.match(healthSummary(r, { kind: "none", why: "" }), /not checked/);
});

test("name matching ignores punctuation and ignores 3-letter noise", () => {
  assert.ok(nameForms({ name: "Better Networking", key: "A-BetterNetworking_Valheim" }).includes("betternetworking"));
  assert.ok(!nameForms({ name: "UI", key: "X-UI" }).length);
});

test("actions: restart only when empty, once, and only for not-seen; pause only on error evidence and only if allowed", () => {
  const missing = judgeModHealth({ family: "valheim", variant: "bepinex", log: BEP_LOG, mods: [{ name: "Silent Thing", key: "Author-SilentThing" }] });
  const base = { report: missing, alreadyRestartedForThisStart: false, autoPause: false, autoRestart: true };
  assert.equal(decideHealthAction({ ...base, playersOnline: 0 }).kind, "restart");
  assert.equal(decideHealthAction({ ...base, playersOnline: 3 }).kind, "notify");
  assert.equal(decideHealthAction({ ...base, playersOnline: null }).kind, "notify");
  assert.equal(decideHealthAction({ ...base, playersOnline: 0, alreadyRestartedForThisStart: true }).kind, "notify");
  assert.equal(decideHealthAction({ ...base, playersOnline: 0, autoRestart: false }).kind, "notify");
  const err = judgeModHealth({ family: "valheim", variant: "bepinex", log: BEP_LOG, mods: [{ name: "Old Mod", key: "Someone-OldMod" }] });
  assert.equal(decideHealthAction({ report: err, playersOnline: 0, alreadyRestartedForThisStart: false, autoPause: false, autoRestart: true }).kind, "notify");
  assert.equal(decideHealthAction({ report: err, playersOnline: 5, alreadyRestartedForThisStart: false, autoPause: true, autoRestart: true }).kind, "pause");
  const both = judgeModHealth({ family: "valheim", variant: "bepinex", log: BEP_LOG, mods: [{ name: "Old Mod", key: "Someone-OldMod" }, { name: "Silent Thing", key: "Author-SilentThing" }] });
  // An error somewhere means a human should look: never a blind restart.
  assert.equal(decideHealthAction({ report: both, playersOnline: 0, alreadyRestartedForThisStart: false, autoPause: false, autoRestart: true }).kind, "notify");
});
