  assert.equal(clientWarningFor({ ...base, categories: ["Server-side", "Tweaks"] }, "bepinex").required, false);
  assert.equal(clientWarningFor({ ...base, categories: ["Server-side", "Client-side"] }, "bepinex").required, true);
});

test("the library mods players always need are curated", () => {
  const j = clientWarningFor({ ...base, sourceId: "ValheimModding-Jotunn", name: "Jotunn" }, "bepinex");
  assert.equal(j.required, true);
  assert.equal(j.basis, "curated");
});

test("Rust plugins and Paper plugins never need a client copy; Fabric mods follow Modrinth's flag", () => {
  assert.equal(clientWarningFor({ gameFamily: "rust", source: "umod", sourceId: "vanish", name: "Vanish" }, "oxide").required, false);
  assert.equal(clientWarningFor({ gameFamily: "minecraft", source: "hangar", sourceId: "x", name: "x" }, "paper").required, false);
  assert.equal(clientWarningFor({ gameFamily: "minecraft", source: "modrinth", sourceId: "sodium", name: "Sodium", clientSide: "required" }, "fabric").required, true);
  assert.equal(clientWarningFor({ gameFamily: "minecraft", source: "modrinth", sourceId: "lithium", name: "Lithium", clientSide: "optional" }, "fabric").required, false);
  assert.equal(clientWarningFor({ gameFamily: "minecraft", source: "modrinth", sourceId: "z", name: "z" }, "fabric").required, null);
});

test("the browse card chip now answers for Thunderstore rows too, and stays null when nobody knows", () => {
  assert.equal(clientRequired({ gameFamily: "valheim", source: "thunderstore", sourceId: "A-B", name: "B", categories: [] }), true);
  assert.equal(clientRequired({ gameFamily: "minecraft", source: "modrinth", sourceId: "z", name: "z", categories: [] }), null);
  assert.equal(clientRequired({ gameFamily: "minecraft", source: "modrinth", sourceId: "z", name: "z", clientSide: "required" }), true);
});
