/**
 * Pure boundary check, split out of `capacityCheckRamMB` so it can be unit-tested
 * with no DB (see test/custom-plan-capacity.test.ts): would adding `addRamMB` to
 * what's already committed push past the ceiling?
 */
export function ramProjectionExceedsCeiling(committedRamMB: number, ceilingRamMB: number, addRamMB: number): boolean {
  return committedRamMB + addRamMB > ceilingRamMB;
}

/**
 * Would committing `ramMB` more push committed RAM past the oversell ceiling?
 * Returns { ok:false, reason } when the host cannot take it.
 *
 * Factored out of `capacityCheck` so a caller that doesn't have (or want) a
 * `Plan` row — a CUSTOM spec, which by definition doesn't match any catalog
 * plan — gets the exact same oversell guard a premade-plan order gets, instead
 * of a second, drifting copy of this math. See lib/custom-plan.ts.
 *
 * Fleet-aware: this used to sum committed RAM across EVERY server (regardless
 * of node) against ONE flat env-configured ceiling — correct with a single
 * node, but wrong the moment a second node exists: it would refuse a valid
 * order the instant the FLEET's total commitment passed one node's worth of
 * capacity, even while the other node sat nearly empty (the opposite of what
 * adding a node is for). `scheduleNode()` (lib/node-capacity.ts) already
 * bin-packs the actual placement across nodes, so this gate asks the same
 * question: is there room on ANY enabled, online node? A server with no
 * `nodeId` (legacy game-server orders, before per-order scheduling existed)
 * is attributed to the primary node, matching `worker/index.ts`'s own
 * `nodeFor()` fallback — otherwise the primary's real load would be
 * undercounted here.
 */
export async function capacityCheckRamMB(ramMB: number): Promise<{ ok: boolean; reason?: string }> {
  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (nodes.length === 0) {
    // No Node rows configured — fall back to the original flat, env-configured
    // single-host ceiling (matches pre-multi-node behavior/tests).
    const snap = await capacitySnapshot();
    if (ramProjectionExceedsCeiling(snap.committedRamMB, snap.ceilingRamMB, ramMB)) {
      return {
        ok: false,
        reason:
          "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
          "Please try a smaller plan or contact support.",
      };
    }
    return { ok: true };
  }

  const primary = nodes.find((n) => n.isPrimary) ?? nodes[0];
  const loads = await Promise.all(
    nodes.map(async (n) => {
      const servers = await db.server.findMany({
        where: {
          status: { not: "DELETING" },
          OR: n.id === primary.id ? [{ nodeId: n.id }, { nodeId: null }] : [{ nodeId: n.id }],
        },
        select: { plan: { select: { ramMB: true } }, gamePlan: { select: { ramMB: true } } },
      });
      const committed = servers.reduce((sum, s) => sum + (s.gamePlan?.ramMB ?? s.plan.ramMB), 0);
      const ceiling = n.capacityRamMB * RAM_OVERSELL_FACTOR;
      return { committed, ceiling };
    })
  );

  const hasRoom = loads.some((l) => !ramProjectionExceedsCeiling(l.committed, l.ceiling, ramMB));
  if (!hasRoom) {
    return {
      ok: false,
      reason:
        "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
        "Please try a smaller plan or contact support.",
    };
  }
  return { ok: true };
}

/**
 * Would deploying `planId` push committed RAM past the oversell ceiling?
 * Returns { ok:false, reason } when the host cannot take the new server.
 */
export async function capacityCheck(planId: string): Promise<{ ok: boolean; reason?: string }> {
  const plan = await db.plan.findUnique({ where: { id: planId }, select: { ramMB: true } });
  if (!plan) return { ok: false, reason: "Plan not found." };
  return capacityCheckRamMB(plan.ramMB);
}

