export type ScheduleOpts = {
  provider?: NodeProvider;
  region?: string;
  // templateVmid: the Proxmox template this order clones (OsTemplate.baseVmid
  // ?? vmid). When given, nodes that do not have it are never chosen — see
  // lib/node-templates.ts for the incident. Omitted = previous behaviour.
  templateVmid?: number | null;
  /**
   * REGION-BOUND placement (2026-10-01): refuse (null) when no candidate is
   * under the critical threshold instead of falling back to the "least-bad"
   * node. Used whenever a region was chosen/resolved, so a full region reports
   * "full" rather than quietly taking one more VM past its limit. Default
   * false keeps the legacy behaviour for the non-region callers.
   */
  strict?: boolean;
  /** Skip the per-call error logging (availability probes run on page render). */
  quiet?: boolean;
};

export type ScheduleDetail = {
  node: Awaited<ReturnType<typeof db.node.findMany>>[number] | null;
  /** Candidates that would stay under the critical RAM threshold after this VM. */
  roomyCount: number;
  /** Candidates that survived the template/guard filters. */
  candidateCount: number;
  /** Lowest projected committed-RAM % across candidates (null = no candidates). */
  bestProjectedPct: number | null;
  /** warn-mode RAM guard flagged every candidate (log-only, but not "plenty of room"). */
  guardFlaggedAll: boolean;
};

export async function scheduleNode(planRamMB: number, opts?: ScheduleOpts) {
  return (await scheduleNodeDetailed(planRamMB, opts)).node;
}

/** scheduleNode plus the facts behind the decision (feeds regionAvailability). */
export async function scheduleNodeDetailed(planRamMB: number, opts?: ScheduleOpts): Promise<ScheduleDetail> {
  const none: ScheduleDetail = { node: null, roomyCount: 0, candidateCount: 0, bestProjectedPct: null, guardFlaggedAll: false };
  // Customer picks a REGION (e.g. "Singapore"), never a specific physical
  // node — multiple nodes can share one region (primary + node-3 are both
  // OVH/sgp1), and forcing a customer's choice onto one specific node meant
  // that node alone ever took new signups for that region, regardless of its
  // actual load relative to its sibling in the same region. Filtering here
  // (rather than a separate function) keeps this the single place "which
  // node wins" is decided, with or without a region constraint.
  const nodes = await db.node.findMany({
    where: {
      enabled: true,
      status: "ONLINE",
      // Distinct from `enabled` — a node can stay visible/online with its
      // existing servers running and still be excluded from taking NEW ones
      // (the admin Infrastructure page's per-node toggle).
      acceptsProvisions: true,
      ...(opts?.region ? { region: opts.region } : {}),
      ...(opts?.provider ? { provider: opts.provider } : {}),
    },
  });
  if (nodes.length === 0) return none;
  let candidates = nodes;
