/**
 * READ-ONLY readiness report for the Enshrouded 1.0 launch window (2026-10-15).
 *
 *   NXEON_DB_TARGET=<db> npx tsx scripts/enshrouded-launch-readiness.ts [region=sgp1]
 *
 * Writes nothing and contacts nothing. It answers, from the DB the node
 * scheduler itself uses: (1) how many Enshrouded servers exist, where, and how
 * much RAM they commit; (2) for each Enshrouded plan, whether `scheduleNode`
 * would place ONE more VM in the region today and how full the best node would
 * be afterwards. It cannot tell how many MORE would fit: run it again after each
 * real order, or read the admin Infrastructure page. Enshrouded is RAM-heavy
 * (plans start at 6 GB), so on tight capacity a launch-day rush is the risk.
 *
 * Needs the owner's session (it reads the production DB). Not run by the build.
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("enshrouded-launch-readiness.ts");

import { db } from "../lib/db";
import { scheduleNodeDetailed } from "../lib/node-capacity";

async function main() {
  const region = process.argv[2] ?? "sgp1";
  const servers = await db.server.findMany({
    where: { status: { not: "DELETING" }, osTemplate: { family: "enshrouded" } },
    select: { status: true, node: { select: { name: true, region: true } }, gamePlan: { select: { ramMB: true } }, autoUpdate: true },
  });
  const byNode = new Map<string, { n: number; ramMB: number }>();
  for (const s of servers) {
    const k = `${s.node?.name ?? "(primary, no node)"} [${s.node?.region ?? "?"}]`;
    const cur = byNode.get(k) ?? { n: 0, ramMB: 0 };
    cur.n++;
    cur.ramMB += s.gamePlan?.ramMB ?? 0;
    byNode.set(k, cur);
  }
  console.log(`Enshrouded servers: ${servers.length} (auto-update on: ${servers.filter((s) => s.autoUpdate).length})`);
  for (const [k, v] of byNode) console.log(`  ${k.padEnd(40)} ${String(v.n).padStart(3)} servers, ${(v.ramMB / 1024).toFixed(0)} GB committed`);

  const plans = await db.gamePlan.findMany({ where: { gameFamily: "enshrouded", active: true }, orderBy: { ramMB: "asc" }, select: { name: true, ramMB: true } });
  console.log(`\nWould one more VM be placed in ${region}? (strict: a full region says no)`);
  for (const p of plans) {
    const d = await scheduleNodeDetailed(p.ramMB, { region, strict: true, quiet: true });
    console.log(
      `  ${p.name.padEnd(40)} ${d.node ? `YES on ${d.node.name}` : "NO"}  roomy nodes=${d.roomyCount}/${d.candidateCount}` +
        (d.bestProjectedPct != null ? `  best projected committed RAM ${d.bestProjectedPct.toFixed(0)}%` : ""),
    );
  }
  console.log("\nRemember: 1.0 needs the new build on the server before 1.0 players can join. The image checks for updates every 30 min (UPDATE_CRON).");
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());
EOF
