/**
 * READ-ONLY: which mod pages earn real search / AI-answer visits, and does each
 * one's "Add to my server" button tell the truth? (growth batch G5, mkt-027)
 *
 *   NXEON_DB_TARGET=<db> npx tsx scripts/mod-page-cta-audit.ts [days=30]
 *
 * Visits come from the Visit table: human (no bot-like user agent) landings on
 * /mods/<family>/<slug> whose referrer is a search engine or an AI answer engine.
 * For each page it prints the verdict of `installSupport` (the same function the
 * page's button and the install action use), so "one click" is never promised
 * for a game/source that can't be installed. Needs the owner's session.
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("mod-page-cta-audit.ts");

import { db } from "../lib/db";
import { installSupport } from "../lib/mod-install-support";

const SEARCH_OR_AI = /(^|\.)(google|bing|duckduckgo|yahoo|ecosia|brave|yandex|baidu|kagi|chatgpt|openai|perplexity|claude|gemini|copilot|you|phind)\./i;
const BOT = /bot|crawl|spider|slurp|preview|headless|python|curl|wget|scrapy|monitor/i;

async function main() {
  const days = Number(process.argv[2] ?? 30);
  const since = new Date(Date.now() - days * 86400_000);
  const rows = await db.visit.findMany({
    where: { path: { startsWith: "/mods/" }, createdAt: { gte: since }, referrer: { not: null } },
    select: { path: true, referrer: true, ua: true },
    take: 200_000,
  });
  const counts = new Map<string, number>();
  for (const r of rows) {
    if (!r.referrer || !SEARCH_OR_AI.test(safeHost(r.referrer))) continue;
    if (r.ua && BOT.test(r.ua)) continue;
    const path = r.path.split("?")[0];
    if (!/^\/mods\/[^/]+\/[^/]+$/.test(path)) continue;
    counts.set(path, (counts.get(path) ?? 0) + 1);
  }
  const ranked = [...counts.entries()].sort((a, b) => b[1] - a[1]);
  console.log(`${ranked.length} mod page(s) with a human search/AI visit in ${days} days\n`);
  for (const [path, n] of ranked) {
    const [, , family, slug] = path.split("/");
    const mod = await db.gameMod.findFirst({ where: { gameFamily: family, slug }, select: { source: true, name: true } });
    const sup = mod ? installSupport(family, mod.source) : null;
    console.log(`${String(n).padStart(4)}  ${path.padEnd(60)} ${mod ? (sup!.ok ? "ONE-CLICK OK" : `manual: ${sup!.message.slice(0, 70)}`) : "(no such mod)"}`);
  }
}

function safeHost(u: string): string {
  try { return new URL(u).hostname + "."; } catch { return ""; }
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());
EOF
